package net.civeira.phylax.feature.observe.observedslo.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LatencyMsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property latency ms of observed slo ")
  void test_latency_ms_v_o_builder() {
    Assertions.assertFalse(LatencyMsVO.nullValue().getLatencyMs().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LatencyMsVO.tryFrom(null).getLatencyMs().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, LatencyMsVO.from(1).getLatencyMs().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LatencyMsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", LatencyMsVO.from(1).toString());
  }
}
